// Lookup returns the metadata for a code. An UNKNOWN code is not an error: a client
// meeting a code added by a newer service renders NextAction, Title, Detail and the
// request id from the response verbatim and treats it as non-retryable.
func Lookup(code Code) (Metadata, bool) {
	meta, found := metadata[code]
	return meta, found
}

// AllCodes returns every published code, in a stable order.
func AllCodes() []Code {
	out := make([]Code, 0, len(codeOrder))
	out = append(out, codeOrder...)
	return out
}

