// RetiredCodeCount is the number of codes withdrawn from service. The names themselves
// live in contracts/errors/error-codes.yaml and are deliberately NOT materialised here:
// a repository-wide grep forbids those strings, and a client never needs to recognise a
// name the service never sends.
const RetiredCodeCount = 1
